macro_rules! deps {
    () => {
        State!();
        Property!();
        Entry!();
        Kind!();
    };
}

macro_rules! resolve_file_type_with_index {
    () => {
        deps!();
        # [doc = " Note that `rela_path` is used as buffer for convenience, but will be left as is when this function returns."] # [doc = " Also note `maybe_file_type` will be `None` for entries that aren't up-to-date and files, for directories at least one entry must be uptodate."] # [doc = " Returns `(maybe_file_type, Option<index_file_type>, flags)`, with the last option being a flag set only for sparse directories in the index."] # [doc = " `index_file_type` is the type of `rela_path` as available in the index."] # [doc = ""] # [doc = " ### Shortcoming"] # [doc = ""] # [doc = " In case-insensitive mode, if there is an entry `d` and a `D/a` both in the index, we will always find the file `d` first, and always consider"] # [doc = " the entry as not uptodate, while classifying it as file (the first one we found). As quite a huge exception, this isn't properly represented"] # [doc = " in the data model, and we emit a trace to make it more obvious when it happens, in case this leads to less expected results."] fn resolve_file_type_with_index (rela_path : & mut BString , index : & gix_index :: State , ignore_case : Option < & gix_index :: AccelerateLookup < '_ > > ,) -> (Option < entry :: Kind > , Option < entry :: Kind > , Option < entry :: Property >) { let mut special_property = None ; fn entry_to_kinds (entry : & gix_index :: Entry) -> (Option < entry :: Kind > , Option < entry :: Kind >) { let kind = if entry . mode . is_submodule () { entry :: Kind :: Repository . into () } else if entry . mode . contains (gix_index :: entry :: Mode :: FILE) { entry :: Kind :: File . into () } else if entry . mode . contains (gix_index :: entry :: Mode :: SYMLINK) { entry :: Kind :: Symlink . into () } else { None } ; (kind . filter (| _ | entry . flags . contains (gix_index :: entry :: Flags :: UPTODATE)) , kind ,) } fn icase_directory_to_kinds (dir : Option < & gix_index :: Entry >) -> (Option < entry :: Kind > , Option < entry :: Kind >) { let index_kind = dir . map (| _ | entry :: Kind :: Directory) ; let uptodate_kind = dir . filter (| entry | entry . flags . contains (gix_index :: entry :: Flags :: UPTODATE)) . map (| _ | entry :: Kind :: Directory) ; (uptodate_kind , index_kind) } let (uptodate_kind , index_kind) = if let Some (accelerate) = ignore_case { match index . entry_by_path_icase (rela_path . as_bstr () , true , accelerate) { None => { icase_directory_to_kinds (index . entry_closest_to_directory_icase (rela_path . as_bstr () , true , accelerate)) } Some (entry) => { let icase_dir = index . entry_closest_to_directory_icase (rela_path . as_bstr () , true , accelerate) ; let directory_matches_exactly = icase_dir . is_some_and (| dir | { let path = dir . path (index) ; let slash_idx = path . rfind_byte (b'/') . expect ("dir") ; path [.. slash_idx] . as_bstr () == rela_path }) ; if directory_matches_exactly { icase_directory_to_kinds (icase_dir) } else { entry_to_kinds (entry) } } } } else { match index . entry_by_path (rela_path . as_bstr ()) { None => { rela_path . push (b'/') ; let res = index . prefixed_entries_range (rela_path . as_bstr ()) ; rela_path . pop () ; let mut one_index_signalling_with_cone = None ; let mut all_excluded_from_worktree_non_cone = false ; let is_tracked = res . is_some () ; let kind = res . filter (| range | { if range . len () == 1 { one_index_signalling_with_cone = range . start . into () ; } let entries = & index . entries () [range . clone ()] ; let any_up_to_date = entries . iter () . any (| e | e . flags . contains (gix_index :: entry :: Flags :: UPTODATE)) ; if ! any_up_to_date && one_index_signalling_with_cone . is_none () { all_excluded_from_worktree_non_cone = entries . iter () . all (| e | e . flags . contains (gix_index :: entry :: Flags :: SKIP_WORKTREE)) ; } any_up_to_date }) . map (| _ | entry :: Kind :: Directory) ; if all_excluded_from_worktree_non_cone || one_index_signalling_with_cone . filter (| _ | kind . is_none ()) . is_some_and (| idx | index . entries () [idx] . mode . is_sparse ()) { special_property = Some (entry :: Property :: TrackedExcluded) ; } (kind , is_tracked . then_some (entry :: Kind :: Directory)) } Some (entry) => entry_to_kinds (entry) , } } ; (uptodate_kind , index_kind , special_property) }
    };
}

resolve_file_type_with_index!();